/**
* Resolves the value of a context variable for a given alias name.
*
* @name resolveContextVarByName
* @memberof REPL.prototype
* @type {Function}
* @param {string} name - variable name
* @returns {*} resolved value
*
* @example
* // Create a new REPL:
* var repl = new REPL();
*
* // Create a new REPL context:
* var ctx = repl.createContext({
*     'a': 5,
*     'b': 10
* });
*
* // Resolve a context variable by name:
* var name = 'a';
* var out = repl.resolveContextVarByName( 'a' );
*
* // Close the REPL:
* repl.close();
*/
